// The only module in this repository that is allowed to ask the operating system where
// things live. Everything else imports from here, so no other file reads a home or temp
// location from an environment variable or writes one as a literal — a blocking constraint
// checks for exactly that, and names the forbidden spellings itself.
//
// The roots are injectable so tests are pure functions of their inputs and can never
// write into a real home directory by accident.

import os from 'node:os';
import path from 'node:path';

const STATE_DIR_NAME = '.prometheus';

export function createPaths({ home, temp } = {}) {
  const homeRoot = () => home ?? os.homedir();
  const tempRoot = () => temp ?? os.tmpdir();

  return {
    homeDir: homeRoot,
    tempDir: tempRoot,
    stateDir: (...parts) => path.join(homeRoot(), STATE_DIR_NAME, ...parts),
    join: (...parts) => path.join(...parts),
  };
}

const defaultPaths = createPaths();

export const homeDir = defaultPaths.homeDir;
export const tempDir = defaultPaths.tempDir;
export const stateDir = defaultPaths.stateDir;
export const join = defaultPaths.join;

lib/kbd/waypoint.mjs.body:
// Port of shared/lib/waypoint.sh (prometheus-skill-pack, 226 lines).
//
// Pure-JS helpers for reading the KBD waypoint, rendering the phase chain, resolving the
// on-disk node dir for an arbitrary-depth path[], and validating worktree-root membership.
//
// Judgment call: the source's `is_descendant` canonicalizes both paths via `cd && pwd -P`
// specifically to defeat a macOS symlink ambiguity (/var vs /private/var). That problem has no
// Windows analogue, so this port uses `fs.realpathSync` — falling back to `path.resolve` when a
// path does not exist yet (e.g. a file about to be created), matching the plan's explicit
// instruction and check-child-scope.mjs's identical need.
//
// Judgment call: `waypointLoad`/`chainSeparator`/`waypointChain`/`kbdNodeChain` take an
// explicit `env` parameter (defaulting to `process.env`) instead of reading `process.env`
// directly, matching this repo's injected-ctx convention (memory.mjs, bottleneck-guard.mjs) so
// locale-dependent behaviour is testable without mutating the real environment.

import { existsSync, readFileSync, realpathSync } from 'node:fs';
import path from 'node:path';

/** Emit every documented waypoint field with its documented default applied. */
export function waypointLoad(filePath) {
  if (!filePath || !existsSync(filePath)) {
    throw new Error(`waypoint_load: missing file: ${filePath}`);
  }
  const raw = JSON.parse(readFileSync(filePath, 'utf8'));
  const s = (value, fallback) => (value === undefined || value === null ? fallback : value);

  const explicitPath = Array.isArray(raw.path) && raw.path.length > 0 ? raw.path : null;
  const derivedPath = [raw.phase, raw.childPointer].filter((v) => v !== undefined && v !== null && v !== '');
  const pathValue = explicitPath ? explicitPath.join(',') : derivedPath.join(',');

  return {
    phase: s(raw.phase, ''),
    previousPhase: s(raw.previousPhase, ''),
    change: s(raw.change, ''),
    status: s(raw.status, ''),
    currentTask: s(raw.currentTask, ''),
    nextPendingChange: s(raw.nextPendingChange, ''),
    sourceTool: s(raw.sourceTool, ''),
    nextChange: s(raw.nextChange, ''),
    nextTask: s(raw.nextTask, ''),
    exactNextCommand: s(raw.exactNextCommand, ''),
    parentPhase: s(raw.parentPhase, ''),
    childPhases: (raw.childPhases ?? []).join(','),
    childPointer: s(raw.childPointer, ''),
    path: pathValue,
    backend: s(raw.backend, ''),
    wave: s(raw.wave, ''),
    lastCompletedChange: s(raw.lastCompletedChange, ''),
    completionMetric: s(raw.completionMetric, 'implementation'),
    implementationCompleted: String(s(raw.implementationCompleted, s(raw.changesCompleted, 0))),
    implementationTotal: String(s(raw.implementationTotal, s(raw.changesTotal, 0))),
    certificationStatus: s(raw.certificationStatus, 'NOT_TRACKED'),
    publicationStatus: s(raw.publicationStatus, 'NOT_TRACKED'),
    updatedAt: s(raw.updatedAt, ''),
  };
}

/** The active chain separator: U+203A `›` + space, or ` > ` under a POSIX/C locale. */
export function chainSeparator(env = process.env) {
  const locale = env.LC_ALL || env.LANG || '';
  if (locale === 'POSIX' || locale === 'C' || locale.startsWith('C.')) return ' > ';
  return '› ';
}

/** Render "parent › phase › pointer" with empty slots elided. */
export function waypointChain(parent, phase, pointer, env = process.env) {
  const sepTrim = chainSeparator(env).trim();
  let out = '';
  if (parent) out = parent;
  if (phase) out = out ? `${out} ${sepTrim} ${phase}` : phase;
  if (pointer) out = out ? `${out} ${sepTrim} ${pointer}` : pointer;
  return out;
}

/** Expand `${HOME}`/`$HOME`/`${USER}`/`$USER` against `env`. Unrecognised tokens pass through. */
export function expandKbdPath(input, env = process.env) {
  let out = input;
  out = out.split('${HOME}').join(env.HOME ?? '');
  out = out.split('${USER}').join(env.USER ?? '');
  out = out.split('$HOME').join(env.HOME ?? '');
  out = out.split('$USER').join(env.USER ?? '');
  return out;
}

/**
 * Canonicalize a path that may not exist yet (e.g. a file about to be created). Resolves the
 * deepest existing ancestor with `fs.realpathSync` — defeating a macOS /var-vs-/private/var
 * symlink ambiguity the same way the source's `cd && pwd -P` did — then rejoins the remaining,
 * not-yet-existing segments. A `path.resolve`-only fallback here would silently disagree with a
 * sibling call that resolved an ancestor which DOES exist (e.g. `root` itself), producing a
 * false "not a descendant" for a not-yet-created nested path.
 */
function canonicalize(target) {
  let existing = target;
  const remainder = [];
  while (!existsSync(existing)) {
    const parent = path.dirname(existing);
    if (parent === existing) break; // reached the filesystem root without finding an ancestor
    remainder.unshift(path.basename(existing));
    existing = parent;
  }
  try {
    return path.join(realpathSync(existing), ...remainder);
  } catch {
    return path.resolve(target);
  }
}

/** Whether `child` is a real descendant of `parent` (same path does NOT count). */
export function isDescendant(child, parent) {
  if (!child || !parent) return false;
  const cChild = canonicalize(child);
  const cParent = canonicalize(parent);
  if (cChild === cParent) return false;
  return cChild.startsWith(cParent + path.sep);
}

/** The on-disk node dir (repo-relative) for an arbitrary-depth path[]. */
export function kbdNodeDir(...segments) {
  if (segments.length < 1) throw new Error('kbdNodeDir: at least one segment is required');
  let out = `.kbd-orchestrator/phases/${segments[0]}`;
  for (const seg of segments.slice(1)) {
    if (!seg) continue;
    out = `${out}/children/${seg}`;
  }
  return out;
}

/** Render the N-level breadcrumb for a path[] array. */
export function kbdNodeChain(segments, env = process.env) {
  if (segments.length < 1) throw new Error('kbdNodeChain: at least one segment is required');
  const sep = chainSeparator(env);
  let out = segments[0];
  for (const seg of segments.slice(1)) {
    if (!seg) continue;
    out = `${out}${sep}${seg}`;
  }
  return out;
}

/** The waypoint's path[] as tokens, synthesized from v2 fields when .path is absent. */
function pathFromWaypoint(waypointPath) {
  if (!existsSync(waypointPath)) return null;
  let parsed;
  try {
    parsed = JSON.parse(readFileSync(waypointPath, 'utf8'));
  } catch {
    return null;
  }
  if (Array.isArray(parsed.path) && parsed.path.length > 0) return parsed.path;
  return [parsed.phase, parsed.childPointer].filter((v) => v !== undefined && v !== null && v !== '');
}

/**
 * The longest existing prefix of the waypoint's path[], trimming stale child pointers instead
 * of propagating non-existent nodes into derived state. `root` anchors the on-disk lookup
 * (defaults to cwd, matching the source's implicit reliance on `$PWD`-relative node dirs).
 */
export function kbdExistingPathTokens(waypointPath, root = '.') {
  const tokens = pathFromWaypoint(waypointPath);
  if (!tokens || tokens.length === 0) return [];

  const valid = [];
  let current = path.join(root, '.kbd-orchestrator', 'phases', tokens[0]);
  if (!existsSync(current)) return [];
  valid.push(tokens[0]);

  for (let i = 1; i < tokens.length; i += 1) {
    const next = path.join(current, 'children', tokens[i]);
    if (!existsSync(next)) break;
    current = next;
    valid.push(tokens[i]);
  }

  return valid;
}

/** Resolve the active node dir (repo-relative) from the waypoint's path[]. */
export function kbdCurrentNodeDir(waypointPath, root = '.') {
  const tokens = kbdExistingPathTokens(waypointPath, root);
  if (tokens.length === 0) return null;
  return kbdNodeDir(...tokens);
}

lib/cadence-adapters/kbd.mjs.body:
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { bindingAt, object, readJson, runJson, writeJson } from './io.mjs';

/** Read-only canonical authority; never substitute a possibly stale waypoint projection. */
export function canonicalSnapshot(project) {
  const state = runJson(process.env.PROMETHEUS_BIN || 'prometheus', ['kbd', '--path', project, 'status', '--json'], project, undefined, 5000);
  const phaseId = state.activePath?.phaseId;
  const phase = state.phases?.[phaseId];
  if (!object(state.phases) || !phase || !Array.isArray(state.activePath.phasePath) || !Number.isInteger(state.revision)) {
    throw new Error('Canonical KBD status lacks phase identity, path, or revision');
  }
  return {
    schemaVersion: 1, source: 'prometheus-kbd-status', projectId: state.projectId, runId: state.runId,
    phaseId, parentPhaseId: phase.parentPhaseId ?? null, path: state.activePath.phasePath,
    revision: state.revision, lifecycle: state.lifecycle, approvals: state.approvals ?? null,
    phases: state.phases, decisions: state.decisions ?? {},
  };
}

export function registerKbd(project, entry) {
  const file = path.join(project, '.kbd-orchestrator', 'hooks-config.json');
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const lock = fs.openSync(`${file}.cadence.lock`, 'wx');
  try {
    const config = fs.existsSync(file) ? readJson(file) : { hooks: [] };
    if (!object(config) || !Array.isArray(config.hooks)) throw new Error('Project hooks configuration must contain a hooks array');
    const hook = { id: 'delivery-cadence-kbd-reconcile', event: 'child:*', mode: 'augment', enabled: true,
      action: { command: 'node', args: [entry, 'reconcile', '--project', project], timeout: 30, on_failure: 'warn' } };
    const prior = config.hooks.find(item => item.id === hook.id);
    if (prior && JSON.stringify(prior) !== JSON.stringify(hook)) throw new Error('Existing cadence hook differs; retain it and resolve the registration explicitly');
    if (!prior) writeJson(file, { ...config, hooks: [...config.hooks, hook] });
    return { status: prior ? 'unchanged' : 'registered', file, hook,
      canonicalCommand: { command: 'node', args: [entry, 'snapshot', '--project', project], cwd: project } };
  } finally { fs.closeSync(lock); fs.rmSync(`${file}.cadence.lock`); }
}

/** Keep the approved operation intact across planning dispatch and child scope splits. */
export function dispatchContext(project, input) {
  if (!object(input) || !object(input.featureOperation)) {
    throw new Error('Dispatch requires the approved featureOperation; name its creation task if the procedure is not implemented');
  }
  const operation = input.featureOperation;
  if (!operation.id || !(operation.promisedCapability || operation.outcome) || !operation.procedure || !operation.checkpointId) {
    throw new Error('Dispatch featureOperation requires id, capability, procedure and checkpointId');
  }
  if (!operation.entrypoint && !operation.creationTaskRef) {
    throw new Error('Dispatch requires a production entrypoint or an approved operation creationTaskRef');
  }
  const canonical = canonicalSnapshot(project);
  if (input.phaseId && input.phaseId !== canonical.phaseId) {
    throw new Error('Dispatch phase differs from the canonical active phase; reconcile the scope before dispatch');
  }
  return { ...input, phaseId: canonical.phaseId, canonical,
    lifecycleAuthority: 'kbd', operationContractSource: input.operationContractSource ?? null };
}

export function reconcileKbd(project) {
  const binding = bindingAt(project);
  if (!binding) return { status: 'degraded', reason: 'cadence-binding-absent' };
  if (typeof binding.stateRoot !== 'string' || typeof binding.skillRoot !== 'string') throw new Error('Cadence binding requires stateRoot and skillRoot');
  const entry = path.resolve(project, binding.skillRoot, 'scripts', 'cadence.mjs');
  const stateRoot = path.resolve(project, binding.stateRoot);
  const state = runJson(process.execPath, [entry, 'status', '--root', stateRoot], project);
  if (!state.activeIterationId) return { status: 'idle', reason: 'no-active-cadence-iteration' };
  const canonical = canonicalSnapshot(project);
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'cadence-kbd-'));
  try {
    const input = path.join(directory, 'canonical.json');
    const authored = binding.dispatchFile ? readJson(path.resolve(project, binding.dispatchFile)) : {};
    if (!object(authored)) throw new Error('Cadence dispatchFile must contain an authored JSON object');
    // Only context flows through the hook; it never creates tasks or certifies a return.
    writeJson(input, { canonical, featureOperation: authored.featureOperation ?? null,
      operationContractSource: binding.dispatchFile ?? null,
      candidateId: authored.candidateId ?? null, workAheadId: authored.workAheadId ?? null });
    return runJson(process.execPath, [entry, 'child', 'reconcile', '--root', stateRoot, '--input', input], project);
  } finally { fs.rmSync(directory, { recursive: true, force: true }); }
}

export async function kbdMain(args, options) {
  const project = path.resolve(args.project ?? process.cwd());
  const action = args._[0] ?? 'reconcile';
  if (action === 'snapshot') return canonicalSnapshot(project);
  if (action === 'register') return registerKbd(project, options.entry);
  if (action === 'dispatch') {
    if (!args.input) throw new Error('Dispatch requires --input with the approved request');
    return dispatchContext(project, readJson(path.resolve(project, args.input)));
  }
  if (action === 'reconcile') {
    try { return reconcileKbd(project); }
    catch { return { status: 'degraded', reason: 'canonical-or-cadence-reconciliation-unavailable' }; }
  }
  throw new Error('Use register, snapshot, dispatch, or reconcile');
}

lib/platform/openspec/state.mjs.body:
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import crypto from 'node:crypto';

export const MINIMUM_VERSION = '1.14.0';
export const REGISTRY = 'https://registry.npmjs.org';
export const cacheHome = () => path.resolve(process.env.PROMETHEUS_OPENSPEC_HOME || path.join(os.homedir(), '.prometheus', 'openspec'));
export const readJson = file => fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, 'utf8')) : null;

export function writeJson(file, value) {
  fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 });
  const temporary = `${file}.${crypto.randomUUID()}.tmp`;
  fs.writeFileSync(temporary, `${JSON.stringify(value, null, 2)}\n`, { mode: 0o600 });
  fs.renameSync(temporary, file);
}

export function acceptedVersion(version) {
  if (!/^\d+\.\d+\.\d+$/.test(version || '')) throw new Error('OpenSpec version must be an exact stable semantic version');
  const actual = version.split('.').map(Number);
  const minimum = MINIMUM_VERSION.split('.').map(Number);
  for (let i = 0; i < 3; i++) {
    if (actual[i] > minimum[i]) return version;
    if (actual[i] < minimum[i]) throw new Error(`OpenSpec ${version} is below minimum ${MINIMUM_VERSION}`);
  }
  return version;
}

export function findProject(start, requireKbd = true) {
  let cursor = path.resolve(start);
  for (;;) {
    const hasKbd = fs.existsSync(path.join(cursor, '.prometheus', 'project.json')) ||
      fs.existsSync(path.join(cursor, '.kbd-orchestrator', 'project.json')) ||
      fs.existsSync(path.join(cursor, '.kbd-orchestrator', 'current-waypoint.json'));
    if (fs.existsSync(path.join(cursor, 'openspec')) && (!requireKbd || hasKbd)) return cursor;
    const parent = path.dirname(cursor);
    if (parent === cursor) return null;
    cursor = parent;
  }
}

export function deadline(timeoutMs) {
  const until = Date.now() + timeoutMs;
  return () => {
    const remaining = until - Date.now();
    if (remaining <= 0) throw Object.assign(new Error('OpenSpec operation exceeded its time budget'), { status: 'pending' });
    return remaining;
  };
}

export function acquireLock(home, operation, project) {
  fs.mkdirSync(home, { recursive: true, mode: 0o700 });
  const file = path.join(home, 'operation.lock');
  let fd;
  try { fd = fs.openSync(file, 'wx', 0o600); }
  catch (error) {
    if (error.code !== 'EEXIST') throw error;
    throw Object.assign(new Error(`OpenSpec operation is locked: ${file}. Inspect the owner; remove only after confirming it has stopped.`), { status: 'contended' });
  }
  fs.writeFileSync(fd, JSON.stringify({ pid: process.pid, operation, project, startedAt: new Date().toISOString() }));
  fs.closeSync(fd);
  return () => fs.unlinkSync(file);
}

export function receipt(home, body) {
  const value = { schemaVersion: 1, time: new Date().toISOString(), ...body };
  const key = crypto.createHash('sha256').update(body.project || 'no-project').digest('hex').slice(0, 24);
  const dir = path.join(home, 'receipts', key);
  const file = path.join(dir, `${Date.now()}-${crypto.randomUUID()}.json`);
  writeJson(file, value);
  writeJson(path.join(dir, 'latest.json'), { ...value, receipt: file });
  return { ...value, receipt: file };
}

lib/services/discovery.mjs.body:
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

const MAX_METADATA_BYTES = 1024 * 1024;
const GENERATION_POINTER = /^generations\/[a-f0-9]{64}$/;

async function readableFile(filename) {
  try {
    return (await fs.stat(filename)).isFile();
  } catch {
    return false;
  }
}

async function readJson(filename) {
  const stat = await fs.stat(filename);
  if (!stat.isFile() || stat.size > MAX_METADATA_BYTES) throw new Error(`Service metadata is not a bounded file: ${filename}`);
  return JSON.parse(await fs.readFile(filename, 'utf8'));
}

async function activeGeneration(pluginRoot) {
  const pointer = path.join(pluginRoot, 'pointers', 'current');
  if (await readableFile(pointer)) {
    const relative = (await fs.readFile(pointer, 'utf8')).trim().replaceAll('\\', '/');
    if (!GENERATION_POINTER.test(relative)) throw new Error(`Invalid Prometheus generation pointer: ${pointer}`);
    return path.join(pluginRoot, ...relative.split('/'));
  }
  try {
    const resolved = await fs.realpath(path.join(pluginRoot, 'current'));
    const relative = path.relative(path.join(pluginRoot, 'generations'), resolved);
    if (!/^[a-f0-9]{64}$/.test(relative)) throw new Error('Current generation escapes the Prometheus store');
    return resolved;
  } catch (error) {
    if (error?.code === 'ENOENT') return null;
    throw error;
  }
}

function platformMarkers(home, platform) {
  if (platform === 'darwin') {
    const root = path.join(home, 'Library', 'LaunchAgents');
    return {
      surrealdb: path.join(root, 'ai.prometheus.surrealdb-native.plist'),
      memory: path.join(root, 'ai.prometheus.surreal-memory-native.plist'),
      liter: path.join(root, 'ai.prometheus.liter-llm-api.plist')
    };
  }
  if (platform === 'linux') {
    const root = path.join(home, '.config', 'systemd', 'user');
    return {
      surrealdb: path.join(root, 'ai.prometheus.surrealdb-native.service'),
      memory: path.join(root, 'ai.prometheus.surreal-memory-native.service'),
      liter: path.join(root, 'ai.prometheus.liter-llm-api.service')
    };
  }
  return {};
}

function candidate(service, endpoint, markers, extra = {}) {
  return {
    id: `${service}:${new URL(endpoint).href}`,
    service,
    endpoint: new URL(endpoint).href,
    provenance: [{
      source: 'full-pack',
      ownership: 'external',
      label: 'Prometheus full pack',
      markers,
      ...extra
    }]
  };
}

/**
 * Discover only documented full-pack locations and endpoints. This never scans
 * the network, reads service environments, imports credentials, or changes a
 * service owned by another installation.
 */
export async function discoverFullPackServices({
  home = os.homedir(),
  platform = process.platform,
  env = process.env
} = {}) {
  const rootMarkers = [];
  const serviceMarkers = { surrealdb: [], memory: [], liter: [] };
  const setupStatePath = path.join(home, '.prometheus', 'setup-state.json');
  let setupState = null;
  if (await readableFile(setupStatePath)) {
    setupState = await readJson(setupStatePath);
    rootMarkers.push(setupStatePath);
  }

  const pluginRoot = path.join(home, '.prometheus', 'plugins', 'prometheus-skill-pack');
  const generation = await activeGeneration(pluginRoot);
  let sourceVersion;
  if (generation) {
    const manifestPath = path.join(generation, 'manifest.json');
    const servicesPath = path.join(generation, 'shared', 'services.manifest.json');
    if (await readableFile(manifestPath)) {
      const manifest = await readJson(manifestPath);
      sourceVersion = typeof manifest.sourceVersion === 'string' ? manifest.sourceVersion : undefined;
      rootMarkers.push(manifestPath);
    }
    if (await readableFile(servicesPath)) {
      const manifest = await readJson(servicesPath);
      const labels = new Set(Array.isArray(manifest.services) ? manifest.services.map((service) => service?.label) : []);
      if (labels.has('ai.prometheus.surrealdb-native')) serviceMarkers.surrealdb.push(servicesPath);
      if (labels.has('ai.prometheus.surreal-memory-native')) serviceMarkers.memory.push(servicesPath);
      if (labels.has('ai.prometheus.liter-llm-api')) serviceMarkers.liter.push(servicesPath);
    }
  }

  for (const [service, filename] of Object.entries(platformMarkers(home, platform))) {
    if (await readableFile(filename)) serviceMarkers[service].push(filename);
  }

  const literConfigs = [
    path.join(home, '.config', 'liter-llm', 'liter-llm-proxy.toml'),
    ...(env.APPDATA ? [path.join(env.APPDATA, 'liter-llm', 'liter-llm-proxy.toml')] : [])
  ];
  const literConfig = (await Promise.all(literConfigs.map(async (filename) => await readableFile(filename) ? filename : null)))
    .find(Boolean);
  if (literConfig) serviceMarkers.liter.push(literConfig);

  const components = setupState?.components && typeof setupState.components === 'object' ? setupState.components : {};
  if (components['surreal-memory-server']) {
    serviceMarkers.surrealdb.push(setupStatePath);
    serviceMarkers.memory.push(setupStatePath);
  }
  if (components['liter-llm']) serviceMarkers.liter.push(setupStatePath);

  const candidates = [];
  if (serviceMarkers.surrealdb.length) {
    candidates.push(candidate('surrealdb', 'http://127.0.0.1:28000', [...new Set(serviceMarkers.surrealdb)], { sourceVersion }));
  }
  if (serviceMarkers.memory.length) {
    candidates.push(candidate('memory', 'http://127.0.0.1:23001/mcp/sse', [...new Set(serviceMarkers.memory)], { sourceVersion }));
  }
  if (serviceMarkers.liter.length) {
    candidates.push(candidate('liter', 'http://127.0.0.1:4000', [...new Set(serviceMarkers.liter)], {
      sourceVersion,
      ...(literConfig ? { configPath: literConfig } : {})
    }));
  }
  return { fullPack: { present: rootMarkers.length > 0, markers: rootMarkers }, candidates };
}

